cards.solution:
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Integer> angka = new ArrayList<Integer>();
        angka.add(30);
        angka.add(70);
        angka.add(55);
        angka.add(10);
        angka.add(90);
        int hitung = 0;
        for (int n : angka) {
            if (n > 50) {
                hitung++;
            }
        }
        System.out.println("Lebih dari 50: " + hitung);
    }
}

